  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --bg: #ffffff; --bg-secondary: #f8fafd; --bg-hover: #f0f3f8; --bg-active: #e8edf5;
      --text: #0D1421; --text-secondary: #58667e; --text-tertiary: #808A9D;
      --border: #eff2f5; --border-strong: #d3d9e2;
      --brand: #3861FB; --brand-light: #eef1fd; --brand-hover: #2951e6;
      --green: #16c784; --green-bg: #e6f9f0; --red: #ea3943; --red-bg: #fde8e9;
      --warning: #f7931a; --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      --radius: 8px; --radius-sm: 6px; --radius-lg: 12px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.04); --shadow: 0 2px 8px rgba(0,0,0,0.08);
    }
    body { font-family: var(--font); background: var(--bg); color: var(--text); line-height: 1.5; -webkit-font-smoothing: antialiased; }
    a { color: var(--brand); text-decoration: none; }
    a:hover { text-decoration: underline; }
    button { font-family: var(--font); cursor: pointer; border: none; background: none; }
    .container { max-width: 1440px; margin: 0 auto; padding: 0 24px; }

    /* Navbar */
    .navbar { border-bottom: 1px solid var(--border); background: var(--bg); position: sticky; top: 0; z-index: 100; }
    .navbar-inner { display: flex; align-items: center; height: 56px; gap: 32px; }
    .nav-brand { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 18px; color: var(--text); white-space: nowrap; }
    .nav-brand svg { flex-shrink: 0; }
    .nav-link { font-size: 14px; font-weight: 500; color: var(--text-secondary); padding: 4px 0; border-bottom: 2px solid transparent; transition: all 0.15s; }
    .nav-link:hover, .nav-link.active { color: var(--text); text-decoration: none; border-bottom-color: var(--brand); }
    .nav-link-dropdown { display: flex; align-items: center; gap: 4px; }
    .nav-right { margin-left: auto; display: flex; align-items: center; gap: 12px; }
    .btn { font-size: 14px; font-weight: 600; padding: 8px 16px; border-radius: var(--radius-sm); transition: all 0.15s; }
    .btn-primary { background: var(--brand); color: #fff; }
    .btn-primary:hover { background: var(--brand-hover); }
    .btn-ghost { color: var(--text); }
    .btn-ghost:hover { background: var(--bg-hover); }

    /* Top Bar Metrics */
    .metrics-bar { background: var(--bg-secondary); border-bottom: 1px solid var(--border); }
    .metrics-inner { display: flex; gap: 32px; padding: 12px 0; overflow-x: auto; }
    .metric-item { display: flex; flex-direction: column; gap: 2px; flex-shrink: 0; }
    .metric-label { font-size: 11px; font-weight: 500; color: var(--text-tertiary); text-transform: uppercase; letter-spacing: 0.5px; }
    .metric-value { font-size: 14px; font-weight: 700; font-variant-numeric: tabular-nums; }
    .metric-change { font-size: 12px; font-weight: 600; }
    .metric-change.up { color: var(--green); } .metric-change.down { color: var(--red); }
    .fear-greed { display: flex; align-items: center; gap: 6px; }
    .fear-greed-badge { font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 10px; }
    .fear-greed-badge.neutral { background: #fef3e0; color: var(--warning); }

    /* Promo Banner */
    .promo-banner { background: linear-gradient(135deg, #1a1f2e 0%, #2d3548 100%); color: #fff; position: relative; overflow: hidden; }
    .promo-inner { display: flex; align-items: center; justify-content: space-between; padding: 14px 0; }
    .promo-text { font-size: 14px; font-weight: 500; display: flex; align-items: center; gap: 8px; }
    .promo-badge { background: var(--brand); font-size: 11px; font-weight: 700; padding: 3px 10px; border-radius: 10px; text-transform: uppercase; letter-spacing: 0.5px; }
    .promo-cta { font-size: 13px; font-weight: 600; color: var(--brand); display: flex; align-items: center; gap: 4px; }
