    .ai-chip:hover { border-color: var(--brand); background: var(--brand-light); }

    /* Network Tabs */
    .network-tabs { border-bottom: 1px solid var(--border); }
    .network-tabs-inner { display: flex; gap: 0; padding: 0; }
    .network-tab { font-size: 13px; font-weight: 500; color: var(--text-secondary); padding: 10px 16px; border-bottom: 2px solid transparent; transition: all 0.15s; }
    .network-tab:hover { color: var(--text); }
    .network-tab.active { color: var(--brand); border-bottom-color: var(--brand); font-weight: 600; }

    /* Category tabs in table */
    .table-controls { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 12px; padding: 16px 0 8px; }
    .category-tabs { display: flex; gap: 24px; }
