    .category-tab:hover { color: var(--text); }
    .category-tab.active { color: var(--text); font-weight: 600; border-bottom-color: var(--text); }
    .table-actions { display: flex; gap: 8px; align-items: center; }
    .btn-sm { font-size: 13px; font-weight: 500; padding: 6px 14px; border-radius: var(--radius-sm); background: var(--bg); border: 1px solid var(--border-strong); color: var(--text); display: flex; align-items: center; gap: 6px; }
    .btn-sm:hover { background: var(--bg-hover); }
    .btn-sm.active { background: var(--brand-light); border-color: var(--brand); color: var(--brand); }
    .sort-arrow { font-size: 10px; color: var(--text-tertiary); }

    /* Panel dropdowns */
    .dropdown-panel { display: none; background: var(--bg); border: 1px solid var(--border-strong); border-radius: var(--radius); box-shadow: var(--shadow); padding: 16px; position: absolute; z-index: 50; min-width: 200px; }
    .dropdown-panel.show { display: block; }
    .dropdown-item { display: flex; align-items: center; gap: 8px; padding: 8px 12px; border-radius: var(--radius-sm); font-size: 13px; cursor: pointer; }
    .dropdown-item:hover { background: var(--bg-hover); }
    .dropdown-item input[type="checkbox"] { accent-color: var(--brand); }
    .filter-panel { display: none; background: var(--bg); border: 1px solid var(--border-strong); border-radius: var(--radius); box-shadow: var(--shadow); padding: 16px; position: absolute; z-index: 50; min-width: 260px; }
    .filter-panel.show { display: block; }
    .filter-row { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; }
    .filter-row label { font-size: 13px; font-weight: 500; width: 80px; flex-shrink: 0; }
    .filter-row input, .filter-row select { font-size: 13px; padding: 6px 10px; border: 1px solid var(--border-strong); border-radius: var(--radius-sm); font-family: var(--font); width: 100%; }

    /* Table */
    .index-row { padding: 12px 0; }
    .index-info { display: flex; align-items: center; gap: 12px; }
    .index-badge { font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 4px; background: #e8edf5; color: var(--text-secondary); letter-spacing: 0.5px; }
    .index-name { font-size: 14px; font-weight: 600; }
    .index-price { font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; }
    .index-change { font-size: 13px; font-weight: 600; }
    .index-change.up { color: var(--green); } .index-change.down { color: var(--red); }

    .table-wrapper { overflow-x: auto; }
    table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
    thead th { font-size: 12px; font-weight: 600; color: var(--text-tertiary); text-align: right; padding: 10px 12px; border-bottom: 2px solid var(--border); white-space: nowrap; user-select: none; cursor: pointer; text-transform: uppercase; letter-spacing: 0.3px; }
    thead th:first-child { text-align: center; }
    thead th:nth-child(2) { text-align: left; }
    thead th:hover { color: var(--text); }
    thead th .sort-icon { margin-left: 4px; font-size: 9px; }
    tbody td { font-size: 14px; padding: 12px 12px; border-bottom: 1px solid var(--border); text-align: right; white-space: nowrap; }
    tbody tr { transition: background 0.1s; }
    tbody tr:hover { background: var(--bg-hover); }
    tbody td:first-child { text-align: center; color: var(--text-tertiary); font-weight: 500; font-size: 13px; }
    tbody td:nth-child(2) { text-align: left; }
    .coin-cell { display: flex; align-items: center; gap: 10px; }
    .coin-icon { width: 28px; height: 28px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 700; color: #fff; flex-shrink: 0; }
    .coin-info { display: flex; flex-direction: column; }
    .coin-name { font-weight: 600; font-size: 14px; color: var(--text); }
    .coin-symbol { font-size: 12px; color: var(--text-tertiary); }
    .price { font-weight: 600; }
    .change { font-weight: 600; font-size: 13px; }
    .change.up { color: var(--green); } .change.down { color: var(--red); }
    .marketcap, .volume { font-weight: 500; }
    .supply { color: var(--text-secondary); font-size: 13px; }
    .sparkline { display: flex; align-items: flex-end; gap: 2px; height: 32px; }
    .sparkline-bar { width: 3px; border-radius: 1px; transition: height 0.3s; }
    .sparkline-bar.up { background: var(--green); } .sparkline-bar.down { background: var(--red); } .sparkline-bar.neutral { background: var(--text-tertiary); }

    /* Pagination */
    .pagination { display: flex; align-items: center; justify-content: center; gap: 4px; padding: 20px 0; flex-wrap: wrap; }
    .page-btn { width: 36px; height: 36px; display: flex; align-items: center; justify-content: center; border-radius: var(--radius-sm); font-size: 14px; font-weight: 500; color: var(--text-secondary); border: 1px solid transparent; }
    .page-btn:hover { background: var(--bg-hover); }
    .page-btn.active { background: var(--brand); color: #fff; font-weight: 600; }
    .page-btn.arrow { font-size: 16px; }
    .page-info { font-size: 13px; color: var(--text-tertiary); margin-left: 16px; }

    /* Market Summary */
    .market-summary { background: var(--bg-secondary); border-top: 2px solid var(--border); padding: 32px 0; }
    .market-summary h2 { font-size: 20px; font-weight: 700; margin-bottom: 16px; }
    .market-summary p { font-size: 14px; color: var(--text-secondary); line-height: 1.8; max-width: 800px; }
    .market-summary .more-btn { display: inline-block; margin-top: 12px; font-size: 14px; font-weight: 600; color: var(--brand); cursor: pointer; }
    .market-summary .more-btn:hover { text-decoration: underline; }
    .market-summary .expanded { display: none; margin-top: 16px; }
    .market-summary .expanded.show { display: block; }
    .market-stats-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 16px; margin-top: 16px; }
    .market-stat-card { background: var(--bg); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px; }
    .market-stat-card .stat-label { font-size: 12px; color: var(--text-tertiary); text-transform: uppercase; letter-spacing: 0.5px; }
    .market-stat-card .stat-value { font-size: 20px; font-weight: 700; margin-top: 4px; }
    .market-stat-card .stat-change { font-size: 13px; font-weight: 600; margin-top: 2px; }

    /* Info Content */
    .info-section { padding: 40px 0; }
    .info-section h2 { font-size: 22px; font-weight: 700; margin-bottom: 12px; }
    .info-section h3 { font-size: 17px; font-weight: 600; margin: 24px 0 8px; }
    .info-section p, .info-section li { font-size: 14px; color: var(--text-secondary); line-height: 1.8; max-width: 780px; }

    /* Footer */
    .footer { background: var(--bg-secondary); border-top: 2px solid var(--border); padding: 48px 0 32px; }
    .footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 32px; }
    .footer-col h4 { font-size: 14px; font-weight: 700; margin-bottom: 12px; }
    .footer-col a { display: block; font-size: 13px; color: var(--text-secondary); padding: 4px 0; }
    .footer-col a:hover { color: var(--text); text-decoration: none; }
    .footer-bottom { margin-top: 32px; padding-top: 20px; border-top: 1px solid var(--border); font-size: 13px; color: var(--text-tertiary); }

    /* Mobile */
    @media (max-width: 768px) {
      .nav-link { display: none; }
      .nav-link.active, .nav-link:nth-child(-n+3) { display: inline; }
      .metrics-inner { gap: 20px; }
      .category-tabs { gap: 16px; overflow-x: auto; padding-bottom: 4px; }
      .category-tab { font-size: 13px; white-space: nowrap; }
      .table-wrapper { margin: 0 -16px; }
      tbody td { font-size: 13px; padding: 10px 8px; }
      .hide-mobile { display: none; }
    }
  </style>
</head>
