  function fmtUSD(v) {
    if (v >= 1e12) return '$' + (v/1e12).toFixed(2) + 'T';
    if (v >= 1e9) return '$' + (v/1e9).toFixed(2) + 'B';
    if (v >= 1e6) return '$' + (v/1e6).toFixed(2) + 'M';
    return '$' + v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
  }

  function fmtPrice(v) {
    if (v >= 100) return '$' + v.toLocaleString('en-US', {minimumFractionDigits: 2, maximumFractionDigits: 2});
    if (v >= 1) return '$' + v.toFixed(2);
    if (v >= 0.01) return '$' + v.toFixed(4);
    if (v >= 0.0001) return '$' + v.toFixed(6);
    return '$' + v.toFixed(8);
  }

  function fmtChange(v) {
    var cls = v > 0 ? 'up' : v < 0 ? 'down' : '';
    var sign = v > 0 ? '+' : '';
    return '<span class="change ' + cls + '">' + sign + v.toFixed(2) + '%</span>';
  }

  function generateSparkline(trend) {
    var bars = '';
    var seed = trend === 'up' ? 0.3 : trend === 'down' ? 0.7 : 0.5;
    var vals = [];
    for (var i = 0; i < 20; i++) {
      seed += (Math.random() - 0.5) * 0.15;
      seed = Math.max(0.05, Math.min(1, seed));
      vals.push(seed);
    }
    if (trend === 'up') {
      for (var i = 0; i < vals.length; i++) vals[i] += i * 0.02;
    } else if (trend === 'down') {
      for (var i = 0; i < vals.length; i++) vals[i] -= i * 0.02;
    }
    var max = Math.max.apply(null, vals), min = Math.min.apply(null, vals);
    var barClass = trend === 'up' ? 'up' : trend === 'down' ? 'down' : 'neutral';
    for (var i = 0; i < vals.length; i++) {
      var h = Math.max(2, ((vals[i] - min) / (max - min || 1)) * 28 + 4);
      bars += '<span class="sparkline-bar ' + barClass + '" style="height:' + h + 'px;"></span>';
    }
    return '<div class="sparkline">' + bars + '</div>';
  }

  var currentPage = 1;
  var currentCategory = 'top';
  var currentNetwork = 'all';
  var itemsPerPage = 100;

  function renderTable(data) {
    var tbody = document.getElementById('crypto-tbody');
    var html = '';
    for (var i = 0; i < data.length; i++) {
      var c = data[i];
      var colorIdx = (c.r - 1) % coinColors.length;
      html += '<tr data-network="' + c.net + '" data-category="top">';
      html += '<td class="col-rank">' + c.r + '</td>';
      html += '<td class="col-name"><div class="coin-cell"><div class="coin-icon" style="background:' + coinColors[colorIdx] + ';">' + c.s.charAt(0) + '</div><div class="coin-info"><span class="coin-name">' + c.n + '</span><span class="coin-symbol">' + c.s + '</span></div></div></td>';
      html += '<td class="col-price"><span class="price">' + fmtPrice(c.p) + '</span></td>';
      html += '<td class="col-1h">' + fmtChange(c.c1) + '</td>';
      html += '<td class="col-24h">' + fmtChange(c.c24) + '</td>';
      html += '<td class="col-7d">' + fmtChange(c.c7) + '</td>';
      html += '<td class="col-mcap"><span class="marketcap">' + fmtUSD(c.mc) + '</span></td>';
      html += '<td class="col-volume"><span class="volume">' + fmtUSD(c.vol) + '</span></td>';
      html += '<td class="col-supply"><span class="supply">' + c.cs + '</span></td>';
      html += '<td class="col-spark">' + generateSparkline(c.trend) + '</td>';
      html += '</tr>';
    }
    tbody.innerHTML = html;
    applyFilters();
  }

  function applyFilters() {
    var rows = document.querySelectorAll('#crypto-tbody tr');
    for (var i = 0; i < rows.length; i++) {
      var row = rows[i];
      var show = true;
      if (currentNetwork !== 'all' && row.dataset.network !== currentNetwork) show = false;
      row.style.display = show ? '' : 'none';
    }
  }

  // Category tab switching
  document.querySelectorAll('.category-tab').forEach(function(tab) {
    tab.addEventListener('click', function() {
      document.querySelectorAll('.category-tab').forEach(function(t) { t.classList.remove('active'); });
      this.classList.add('active');
      currentCategory = this.dataset.category;
      // In a real app, this would fetch different data. For demo, we shuffle the displayed data slightly
      renderTable(cryptos);
    });
  });

  // Network filter switching
  document.querySelectorAll('.network-tab').forEach(function(tab) {
    tab.addEventListener('click', function() {
      document.querySelectorAll('.network-tab').forEach(function(t) { t.classList.remove('active'); });
      this.classList.add('active');
      currentNetwork = this.dataset.network;
      applyFilters();
    });
  });

  // Pagination
  document.querySelectorAll('.page-btn').forEach(function(btn) {
    btn.addEventListener('click', function() {
      if (this.classList.contains('arrow') || this.textContent === '...') return;
      document.querySelectorAll('.page-btn').forEach(function(b) { b.classList.remove('active'); });
      this.classList.add('active');
      currentPage = parseInt(this.textContent);
      var start = (currentPage - 1) * itemsPerPage;
      var pageData = cryptos.slice(start, start + itemsPerPage);
      if (pageData.length > 0) {
        renderTable(pageData);
      }
    });
  });

  // Toggle dropdowns
  function toggleDropdown(id) {
    var panel = document.getElementById(id);
    var isShowing = panel.classList.contains('show');
    // Close all dropdowns
    document.querySelectorAll('.dropdown-panel.show, .filter-panel.show').forEach(function(p) { p.classList.remove('show'); });
    if (!isShowing) panel.classList.add('show');
    event.stopPropagation();
  }

  // Close dropdowns on click outside
  document.addEventListener('click', function(e) {
    if (!e.target.closest('.dropdown-panel') && !e.target.closest('.filter-panel') && !e.target.closest('.btn-sm')) {
      document.querySelectorAll('.dropdown-panel.show, .filter-panel.show').forEach(function(p) { p.classList.remove('show'); });
    }
  });

  // Toggle columns
  function toggleColumn(cls, checkbox) {
    var els = document.querySelectorAll('.' + cls);
    for (var i = 0; i < els.length; i++) {
      els[i].style.display = checkbox.checked ? '' : 'none';
    }
  }

  // Read More accordion
  function toggleReadMore() {
    var content = document.getElementById('read-more-content');
    var btn = document.getElementById('read-more-btn');
    var isShowing = content.classList.contains('show');
    if (isShowing) {
      content.classList.remove('show');
      btn.textContent = 'Read More ▸';
    } else {
      content.classList.add('show');
      btn.textContent = 'Read Less ▴';
    }
  }

  // Promo banner rotation
  var promos = [
    {badge:'NEW',text:'CT<span style="color:var(--brand)">P</span> Launch: Secure $GENIUS Airdrop — Join Now'},
    {badge:'HOT',text:'Featured Partner: Ecosystem Rewards Program Now Live — Claim Your Share'},
    {badge:'ALERT',text:'Market Update: Bitcoin dominance reaches new monthly high'}
  ];
  var promoIndex = 0;
  setInterval(function() {
    promoIndex = (promoIndex + 1) % promos.length;
    var p = promos[promoIndex];
    document.querySelector('.promo-text').innerHTML = '<span class="promo-badge">' + p.badge + '</span> ' + p.text;
    var dots = document.querySelectorAll('.promo-dot');
    for (var i = 0; i < dots.length; i++) {
      dots[i].classList.toggle('active', i === promoIndex);
    }
  }, 5000);

  // Initial render
  renderTable(cryptos);
</script>
</body>
</html>
